func (this *Dydx) ParseLedgerEntry(item any, optionalArgs ...any) any {
	//
	// {
	//     "id": "6a6075bc-7183-5fd9-bc9d-894e238aa527",
	//     "sender": {
	//         "address": "dydx14zzueazeh0hj67cghhf9jypslcf9sh2n5k6art",
	//         "subaccountNumber": 0
	//     },
	//     "recipient": {
	//         "address": "dydx1slanxj8x9ntk9knwa6cvfv2tzlsq5gk3dshml0",
	//         "subaccountNumber": 1
	//     },
	//     "size": "0.000001",
	//     "createdAt": "2025-07-29T09:43:02.105Z",
	//     "createdAtHeight": "45116125",
	//     "symbol": "USDC",
	//     "type": "TRANSFER_OUT",
	//     "transactionHash": "92B4744BA1B783CF37C79A50BEBC47FFD59C8D5197D62A8485D3DCCE9AF220AF"
	// }
	//
	currency := GetArg(optionalArgs, 0, nil)
	_ = currency
	var currencyId any = this.SafeString(item, "symbol")
	var code any = this.SafeCurrencyCode(currencyId, currency)
	currency = this.SafeCurrency(currencyId, currency)
	var typeVar any = this.SafeStringUpper(item, "type")
	var direction any = nil
	if IsTrue(!IsEqual(typeVar, nil)) {
		if IsTrue(IsTrue(IsEqual(typeVar, "TRANSFER_IN")) || IsTrue(IsEqual(typeVar, "DEPOSIT"))) {
			direction = "in"
		} else if IsTrue(IsTrue(IsEqual(typeVar, "TRANSFER_OUT")) || IsTrue(IsEqual(typeVar, "WITHDRAWAL"))) {
			direction = "out"
		}
	}
	var amount any = this.SafeString(item, "size")
	var timestamp any = this.Parse8601(this.SafeString(item, "createdAt"))
	var sender any = this.SafeDict(item, "sender")
	var recipient any = this.SafeDict(item, "recipient")
	return this.SafeLedgerEntry(map[string]any{
		"info":             item,
		"id":               this.SafeString(item, "id"),
		"direction":        direction,
		"account":          this.SafeString(sender, "address"),
		"referenceAccount": this.SafeString(recipient, "address"),
		"referenceId":      this.SafeString(item, "transactionHash"),
		"type":             this.ParseLedgerEntryType(typeVar),
		"currency":         code,
		"amount":           this.ParseNumber(amount),
		"timestamp":        timestamp,
		"datetime":         this.Iso8601(timestamp),
		"before":           nil,
		"after":            nil,
		"status":           nil,
		"fee":              nil,
	}, currency)
}
func (this *Dydx) ParseLedgerEntryType(typeVar any) any {
	var ledgerType map[string]any = map[string]any{
		"TRANSFER_IN":  "transfer",
		"TRANSFER_OUT": "transfer",
		"DEPOSIT":      "deposit",
		"WITHDRAWAL":   "withdrawal",
	}
	return this.SafeString(ledgerType, typeVar, typeVar)
}

