/**
 * @method
 * @name dydx#transfer
 * @description transfer currency internally between wallets on the same account
 * @param {string} code unified currency code
 * @param {float} amount amount to transfer
 * @param {string} fromAccount account to transfer from *main, subaccount*
 * @param {string} toAccount account to transfer to *subaccount, address*
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {string} [params.vaultAddress] the vault address for order
 * @returns {object} a [transfer structure]{@link https://docs.ccxt.com/?id=transfer-structure}
 */
func (this *Dydx) Transfer(code string, amount float64, fromAccount string, toAccount string, options ...TransferOptions) (TransferEntry, error) {

	opts := TransferOptionsStruct{}

	for _, opt := range options {
		opt(&opts)
	}

	var params *map[string]any = opts.Params
	res := <-this.TransferAsync(code, amount, fromAccount, toAccount, params)
	if IsError(res) {
		return TransferEntry{}, CreateReturnError(res)
	}
	return NewTransferEntry(res), nil
}

/**
 * @method
 * @name dydx#fetchTransfers
 * @description fetch a history of internal transfers made on an account
 * @see https://docs.dydx.xyz/indexer-client/http#get-transfers
 * @param {string} code unified currency code of the currency transferred
 * @param {int} [since] the earliest time in ms to fetch transfers for
 * @param {int} [limit] the maximum number of transfers structures to retrieve
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {string} [params.address] wallet address that made trades
 * @param {string} [params.subAccountNumber] sub account number
 * @returns {object[]} a list of [transfer structures]{@link https://docs.ccxt.com/?id=transfer-structure}
 */
func (this *Dydx) FetchTransfers(options ...FetchTransfersOptions) ([]TransferEntry, error) {

	opts := FetchTransfersOptionsStruct{}

	for _, opt := range options {
		opt(&opts)
	}

	var code *string = opts.Code

	var since *int64 = opts.Since

	var limit *int64 = opts.Limit

	var params *map[string]any = opts.Params
	res := <-this.FetchTransfersAsync(code, since, limit, params)
	if IsError(res) {
		return nil, CreateReturnError(res)
	}
	return NewTransferEntryArray(res), nil
}

/**
 * @method
 * @name dydx#withdraw
 * @description make a withdrawal
 * @param {string} code unified currency code
 * @param {float} amount the amount to withdraw
 * @param {string} address the address to withdraw to
 * @param {string} tag
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} a [transaction structure]{@link https://docs.ccxt.com/?id=transaction-structure}
 */
func (this *Dydx) Withdraw(code string, amount float64, address string, options ...WithdrawOptions) (Transaction, error) {

	opts := WithdrawOptionsStruct{}

	for _, opt := range options {
		opt(&opts)
	}

	var tag *string = opts.Tag

	var params *map[string]any = opts.Params
	res := <-this.WithdrawAsync(code, amount, address, tag, params)
	if IsError(res) {
		return Transaction{}, CreateReturnError(res)
	}
	return NewTransaction(res), nil
}

